package com.eversorhn.laun.data

/**
 * LAUN's own tile icon set — 300 monochrome glyphs in 10 categories, drawn in the same angular
 * vocabulary as the hex grid, selectable per tile as an alternative to the app's name text or its
 * real launcher icon (see [BUILTIN_ICON_PACK]).
 *
 * Each icon is stored as its pre-flattened drawing program rather than as SVG markup: every
 * source shape (rect/circle/line/polyline/polygon/ellipse) was converted to plain path data at
 * generation time, so the app never needs an SVG parser — only Compose's own PathParser. [ops] is
 * a `;`-separated list of draw operations, each `flags|pathData`, where flags is a `~`-separated
 * set of single-letter directives, all optional and all defaulting to "stroke in the tile's
 * current color":
 *
 * - `f`             fill this path instead of stroking it
 * - `o<alpha>`      draw at this alpha (0..1)
 * - `w<width>`      stroke width in viewport units, instead of [BUILTIN_ICON_STROKE]
 * - `a<on>,<off>`   dashed stroke with this on/off pattern
 * - `t<dx>,<dy>`    translate before drawing
 * - `r<deg>,<x>,<y>` rotate by deg around (x, y) before drawing
 *
 * Path coordinates are in a [BUILTIN_ICON_VIEWPORT]-unit square and scaled at draw time.
 */
data class BuiltinIcon(
    /** Stable id persisted in tile icon overrides — never renumber or reuse. */
    val id: String,
    val label: String,
    val category: String,
    val ops: String
)

/** Coordinate space every icon's path data is authored in. */
const val BUILTIN_ICON_VIEWPORT = 48f

/** Default stroke width, in viewport units. */
const val BUILTIN_ICON_STROKE = 3.2f

/**
 * Sentinel "icon pack" id for LAUN's own set, stored in the same per-app override map real
 * installed icon packs use — it can never collide with a real one, since Android package names
 * can't contain a space.
 */
const val BUILTIN_ICON_PACK = "LAUN BUILT-IN"

